export const meta = {
  name: 'write-haikus',
  description: 'Write three haiku files (rivers, mountains, cities) in parallel, one agent per file',
  phases: [{ title: 'Write', detail: 'one agent per haiku file' }],
}

const DIR = '/workspace/fanoutfuse/repo/docs/evidence/2026-10-18/ultracode/project'
const FILES = [
  { name: 'a.txt', topic: 'rivers' },
  { name: 'b.txt', topic: 'mountains' },
  { name: 'c.txt', topic: 'cities' },
]

const RESULT = {
  type: 'object',
  properties: {
    path: { type: 'string' },
    haiku: { type: 'string' },
    written: { type: 'boolean' },
  },
  required: ['path', 'haiku', 'written'],
}

phase('Write')
const results = await parallel(FILES.map(f => () =>
  agent(
    `Write an original haiku about ${f.topic}: three lines, 5-7-5 syllables. ` +
    `Save it as the entire contents of the file ${DIR}/${f.name} (exactly the three lines, ending with a single trailing newline) using the Write tool. ` +
    `Do not create or modify any other file. Then read the file back to confirm its contents. ` +
    `Return the absolute path, the haiku text, and whether the write was confirmed.`,
    { label: `write:${f.name}`, phase: 'Write', schema: RESULT, effort: 'low' }
  )
))

return results.map((r, i) => ({ file: FILES[i].name, topic: FILES[i].topic, ...(r || { written: false }) }))

